mapper.select:
SELECT bs.*, pa.name as account_name
FROM bank_statements bs
LEFT JOIN payment_account pa ON bs.account_id = pa.id
WHERE bs.account_id = #{accountId}
AND bs.transaction_date BETWEEN #{startDate} AND #{endDate}
ORDER BY bs.transaction_date DESC

SELECT bs.*, pa.name as account_name
FROM bank_statements bs
LEFT JOIN payment_account pa ON bs.account_id = pa.id
WHERE 1=1

    AND bs.account_id = #{accountId}


    AND bs.type = #{type}


    AND bs.transaction_date >= #{startDate}


    AND bs.transaction_date <= #{endDate}


    AND bs.description LIKE CONCAT('%', #{description}, '%')

ORDER BY bs.transaction_date DESC

SELECT 
    COUNT(*) AS total_count,
    SUM(CASE WHEN type = 'income' THEN amount ELSE 0 END) AS total_income,
    SUM(CASE WHEN type = 'expense' THEN amount ELSE 0 END) AS total_expense,
    SUM(CASE WHEN type = 'income' THEN amount ELSE 0 END) - SUM(CASE WHEN type = 'expense' THEN amount ELSE 0 END) AS net_amount
FROM bank_statements
WHERE 1=1

    AND account_id = #{accountId}


    AND transaction_date >= #{startDate}


    AND transaction_date <= #{endDate}

SELECT bs.*, pa.name as account_name
FROM bank_statements bs
LEFT JOIN payment_account pa ON bs.account_id = pa.id
WHERE 1=1

    AND bs.account_id = #{accountId}


    AND bs.type = #{type}


    AND bs.transaction_date >= #{startDate}


    AND bs.transaction_date <= #{endDate}


    AND bs.description LIKE CONCAT('%', #{description}, '%')

ORDER BY bs.transaction_date DESC
LIMIT #{pageSize} OFFSET #{offset}

SELECT COUNT(*)
FROM bank_statements
WHERE 1=1

    AND account_id = #{accountId}


    AND type = #{type}


    AND transaction_date >= #{startDate}


    AND transaction_date <= #{endDate}


    AND description LIKE CONCAT('%', #{description}, '%')
